list_dashboards.code:
final response = await client.dashboards.listDashboards();
for (final dashboard in (response.map as Map)['dashboards'] as List) {
  print('${(dashboard as Map)['id']} ${dashboard['name']} ${dashboard['default']}');
}

create_dashboard.code:
final response = await client.dashboards.createDashboard({
  'name': 'Weekly',
  'kpis': ['total_sales', 'total_orders', 'aov'],
});
final dashboard = response.map as Map;
print('${dashboard['id']} ${dashboard['name']} ${dashboard['default']}');

get_dashboard.code:
final response = await client.dashboards
    .getDashboard('3f2b8c1e-7a4d-4e29-9b1a-5c6d7e8f9a01');
final dashboard = response.map as Map;
print(dashboard['name']);
for (final section in dashboard['standard_sections'] as List) {
  print('${(section as Map)['key']} ${section['visible']}');
}

patch_dashboard.code:
final response = await client.dashboards.patchDashboard(
  '3f2b8c1e-7a4d-4e29-9b1a-5c6d7e8f9a01',
  {
    'standard_sections': [
      {'key': 'announcement', 'visible': false},
    ],
  },
);
for (final section in (response.map as Map)['standard_sections'] as List) {
  print('${(section as Map)['key']} ${section['visible']}');
}
